query.expr:
s -> {
	title = $s.get(`tl.ai.execution:AgentSession#title`);
	owner = $s.get(`tl.ai.execution:AgentSession#owner`);
	createdAt = $s.get(`tl.ai.execution:AgentSession#createdAt`);
	fallback =
		ifElse(isEmpty($owner), "", $owner.label() + ifElse(isEmpty($createdAt), "", " - "))
		+ ifElse(isEmpty($createdAt), "", dateFormat("yyyy-MM-dd HH:mm:ss").format($createdAt));
	ifElse(isEmpty($title), $fallback, $title);
}

e -> {
	agentName = $e.get(`tl.ai.execution:AgentExecution#agentName`);
	startedAt = $e.get(`tl.ai.execution:AgentExecution#startedAt`);
	runId = $e.get(`tl.ai.execution:AgentExecution#runId`);
	shortId = ifElse(length($runId) > 6, $runId.subString(0, 6), $runId);
	$agentName
		+ ifElse(isEmpty($startedAt), "", " - " + dateFormat("yyyy-MM-dd HH:mm:ss").format($startedAt))
		+ ifElse(isEmpty($shortId), "", " (" + $shortId + ")");
}

macro.expr:
e -> {
	raw = $e.get(`tl.ai.execution:AgentExecution#transcript`);
	maxChars = 500000;
	time = dateFormat("HH:mm:ss");
	stamp = ms -> ifElse(isEmpty($ms), "", $time.format($ms.toDate()));

	// The discriminator of a part is a JSON token; the panel names the kind.
	kindLabels = {
		'text': #('Text'@en, 'Text'@de),
		'thinking': #('Thinking'@en, 'Denken'@de),
		'tool_call': #('Tool call'@en, 'Tool-Aufruf'@de),
		'approval': #('Approval'@en, 'Freigabe'@de),
		'interaction': #('Question'@en, 'Rückfrage'@de),
		'compaction': #('Compaction'@en, 'Verdichtung'@de),
		'error': #('Error'@en, 'Fehler'@de),
		'transaction': #('Transaction'@en, 'Transaktion'@de),
		'delegation': #('Delegation'@en, 'Delegation'@de),
		'system': #('System'@en, 'System'@de)
	};
	kind = t -> ifElse(isEmpty($kindLabels[$t]), $t, $kindLabels[$t]);

	// One expression per class attribute rather than literal text plus an embedding: the macro
	// writer separates the parts of an attribute value with a space, which would break the
	// modifier class in two.
	stateClass = v -> 'aiTrState aiTrState-' + ifElse(isEmpty($v), 'UNKNOWN', $v);

	// Everything a part can carry except the nested parts of a delegation.
	// Shared by the top-level renderer and the renderer for a sub-agent's
	// parts, so a tool call looks the same wherever it appears.
	body = p -> {
		text = $p['textData'];
		thinking = $p['thinkingData'];
		call = $p['toolCallData'];
		approval = $p['approvalData'];
		ask = $p['interactionData'];
		compaction = $p['compactionData'];
		error = $p['errorData'];
		transaction = $p['transactionData'];
		delegation = $p['delegationData'];
		system = $p['systemData'];
		{{{
			<div class="aiTrHead">
				<span class="aiTrKind">{$kind($p['type'])}</span>
				<span class="aiTrTime">{$stamp($p['timestamp'])}</span>
			</div>
			{ isEmpty($text) ? "" : {{{
				<div class="aiTrText">{$text['text']}</div>
			}}} }
			{ isEmpty($thinking) ? "" : {{{
				<div class="aiTrThinking">{$thinking['text']}</div>
			}}} }
			{ isEmpty($system) ? "" : {{{
				<div class="aiTrLine"><b>{$system['eventType']}</b> {$system['details']}</div>
			}}} }
			{ isEmpty($call) ? "" : {{{
				<div class="aiTrLine">
					<code class="aiTrName">{$call['toolName']}</code>
					<span class="{$stateClass($call['status'])}">{$call['status']}</span>
					<span class="aiTrTime">{$call['durationMs']} ms</span>
				</div>
				{ isEmpty($call['argsJson']) ? "" : {{{
					<pre class="aiTrCode">{$call['argsJson']}</pre>
				}}} }
				{ isEmpty($call['result']) ? "" : {{{
					<pre class="aiTrCode">{$call['result']}</pre>
				}}} }
				{ isEmpty($call['resultRef']) ? "" : {{{
					<div class="aiTrLine">{$call['resultRef']}</div>
				}}} }
				{ isEmpty($call['errorMessage']) ? "" : {{{
					<div class="aiTrAlert">{$call['errorMessage']}</div>
				}}} }
				{ isEmpty($call['denyReason']) ? "" : {{{
					<div class="aiTrWarn">{$call['denyReason']}</div>
				}}} }
			}}} }
			{ isEmpty($approval) ? "" : {{{
				<div class="aiTrLine">
					<code class="aiTrName">{$approval['toolName']}</code>
					<span class="{$stateClass($approval['decision'])}">{$approval['decision']}</span>
				</div>
				{ isEmpty($approval['displayReason']) ? "" : {{{
					<div class="aiTrText">{$approval['displayReason']}</div>
				}}} }
				{ isEmpty($approval['argsJson']) ? "" : {{{
					<pre class="aiTrCode">{$approval['argsJson']}</pre>
				}}} }
				{ isEmpty($approval['userComment']) ? "" : {{{
					<div class="aiTrAnswer">{$approval['userComment']}</div>
				}}} }
			}}} }
			{ isEmpty($ask) ? "" : {{{
				<div class="aiTrLine">
					<b>{$ask['header']}</b>
					<span class="aiTrState">{$ask['interactionType']}</span>
				</div>
				<div class="aiTrText">{$ask['question']}</div>
				{ isEmpty($ask['options']) ? "" : {{{
					<div class="aiTrLine">{foreach($ask['options'], o -> {{{ <span class="aiTrOption">{$o}</span> }}})}</div>
				}}} }
				{ isEmpty($ask['userResponse']) ? "" : {{{
					<div class="aiTrAnswer">{$ask['userResponse']}</div>
				}}} }
			}}} }
			{ isEmpty($transaction) ? "" : {{{
				<div class="aiTrLine">
					<span class="{$stateClass($transaction['type'])}">{$transaction['type']}</span>
					<span class="aiTrTime">r{$transaction['revisionNumber']}</span>
					{$transaction['reason']}
				</div>
			}}} }
			{ isEmpty($compaction) ? "" : {{{
				<div class="aiTrLine">
					{$compaction['tokensBefore']} → {$compaction['tokensAfter']} Token
					<span class="aiTrState">{$compaction['trigger']}</span>
				</div>
			}}} }
			{ isEmpty($error) ? "" : {{{
				<div class="aiTrAlert"><b>{$error['kind']}</b> {$error['errorMessage']}</div>
			}}} }
			{ isEmpty($delegation) ? "" : {{{
				<div class="aiTrLine">
					<code class="aiTrName">{$delegation['fromAgent']}</code>
					→
					<code class="aiTrName">{$delegation['toAgent']}</code>
					<span class="{$stateClass($delegation['stopReason'])}">{$delegation['stopReason']}</span>
				</div>
				{ isEmpty($delegation['inputSummary']) ? "" : {{{
					<div class="aiTrText">{$delegation['inputSummary']}</div>
				}}} }
				{ isEmpty($delegation['resultSummary']) ? "" : {{{
					<div class="aiTrAnswer">{$delegation['resultSummary']}</div>
				}}} }
			}}} }
		}}};
	};

	// A sub-agent's own parts. A delegation nested inside one of them is
	// only announced by its header line: rendering it in full would need a
	// self-referencing function, and a TL-Script closure captures its
	// context before the name it would refer to is bound.
	nested = p -> {{{
		<div class="aiTrPart aiTrNested">{$body($p)}</div>
	}}};

	part = p -> {
		children = ifElse(isEmpty($p['delegationData']), list(), $p['delegationData']['childParts']);
		{{{
			<div class="aiTrPart">
				{$body($p)}
				{ isEmpty($children) ? "" : {{{
					<details class="aiTrChildren">
						<summary>{#('{0} nested parts of the sub-agent'@en, '{0} verschachtelte Teile des Teilagenten'@de).fill($children.size())}</summary>
						{foreach($children, c -> $nested($c))}
					</details>
				}}} }
			</div>
		}}};
	};

	turn = t -> {
		usage = $t['usage'];
		// What the host stated about this turn. Shown with the turn and not with the
		// user's parts, because it is not the user's text: it travels beside it.
		context = $t['turnContext'];
		{{{
			<details class="aiTrTurn" open="open">
				<summary>
					<span class="aiTrTurnNo">{#('Turn {0}'@en, 'Turn {0}'@de).fill($t['turnNumber'])}</span>
					<span class="aiTrTime">{$stamp($t['timestamp'])}</span>
					<span class="aiTrTime">{$t['model']}</span>
					{ isEmpty($usage) ? "" : {{{
						<span class="aiTrTime">{$usage['inputTokens'] + $usage['outputTokens']} Token</span>
					}}} }
				</summary>
				{ isEmpty($context) ? "" : {{{
					<div class="aiTrContext">
						<div class="aiTrHead">
							<span class="aiTrKind">{#('Turn context'@en, 'Turn-Kontext'@de)}</span>
						</div>
						<pre class="aiTrCode">{$context}</pre>
					</div>
				}}} }
				{foreach($t['userParts'], p -> {{{ <div class="aiTrUser">{$part($p)}</div> }}})}
				{foreach($t['assistantParts'], p -> $part($p))}
			</details>
		}}};
	};

	isEmpty($raw) ? {{{
		<div class="aiTrNote">{#('No transcript. It is written when the run finishes, so a running or a crashed run has none.'@en, 'Kein Transkript. Es wird beim Abschluss des Laufs geschrieben - ein laufender oder abgestürzter Lauf hat keines.'@de)}</div>
	}}} : (length($raw) > $maxChars ? {{{
		<div class="aiTrNote aiTrWarn">{#('The transcript is {0} characters long and is not rendered here. The raw value is in the group below.'@en, 'Das Transkript ist {0} Zeichen lang und wird hier nicht dargestellt. Der Rohwert steht in der Gruppe darunter.'@de).fill(length($raw))}</div>
	}}} : {
		turns = parseJson($raw)['turns'];
		{{{
			<div class="aiTr">
				<div class="aiTrNote">{#('Recorded turns: {0}'@en, 'Aufgezeichnete Turns: {0}'@de).fill($turns.size())}</div>
				{foreach($turns, t -> $turn($t))}
			</div>
		}}};
	});
}

query.expr:
r -> {
	header = $r.get(`tl.ai.execution:InteractionRequest#header`);
	prompt = regex("\\s+").regexReplace($r.get(`tl.ai.execution:InteractionRequest#prompt`), " ");
	excerpt = ifElse(length($prompt) > 60, $prompt.subString(0, 60) + "...", $prompt);
	subject = ifElse(isEmpty($header), $excerpt, $header);
	type = $r.get(`tl.ai.execution:InteractionRequest#type`);
	createdAt = $r.get(`tl.ai.execution:InteractionRequest#createdAt`);
	ifElse(isEmpty($type), "", $type.label())
		+ ifElse(isEmpty($subject), "", ": " + $subject)
		+ ifElse(isEmpty($createdAt), "", " (" + dateFormat("yyyy-MM-dd HH:mm:ss").format($createdAt) + ")");
}
